insert into _qbank_seed values
  ('mathematics', "1.1", null, "Types of number, sets, powers and roots — Core Paper 1 (non-calculator)", $json$[{"question_text":"Find the HCF of 30 and 40.","options":["11","20","12","10"],"correct_option":3,"difficulty":"medium","explanation":"Common factors of 30 and 40 give HCF = 10.","sort_order":1},{"question_text":"Find the LCM of 8 and 16.","options":["16","17","8","128"],"correct_option":0,"difficulty":"medium","explanation":"LCM = (8 × 16) ÷ HCF(8) = 16.","sort_order":2},{"question_text":"Find the HCF of 24 and 34.","options":["10","2","4","5"],"correct_option":1,"difficulty":"medium","explanation":"Common factors of 24 and 34 give HCF = 2.","sort_order":3},{"question_text":"Find the LCM of 8 and 20.","options":["21","160","20","40"],"correct_option":3,"difficulty":"medium","explanation":"LCM = (8 × 20) ÷ HCF(4) = 40.","sort_order":4},{"question_text":"Find the HCF of 24 and 36.","options":["24","14","12","13"],"correct_option":2,"difficulty":"medium","explanation":"Common factors of 24 and 36 give HCF = 12.","sort_order":5},{"question_text":"Find the LCM of 6 and 16.","options":["16","96","48","24"],"correct_option":2,"difficulty":"medium","explanation":"LCM = (6 × 16) ÷ HCF(2) = 48.","sort_order":6},{"question_text":"Find the HCF of 36 and 42.","options":["6","7","12","8"],"correct_option":0,"difficulty":"medium","explanation":"Common factors of 36 and 42 give HCF = 6.","sort_order":7},{"question_text":"Find the LCM of 9 and 24.","options":["36","24","72","216"],"correct_option":2,"difficulty":"medium","explanation":"LCM = (9 × 24) ÷ HCF(3) = 72.","sort_order":8},{"question_text":"Find the HCF of 18 and 24.","options":["7","6","8","12"],"correct_option":1,"difficulty":"medium","explanation":"Common factors of 18 and 24 give HCF = 6.","sort_order":9},{"question_text":"Find the LCM of 15 and 21.","options":["105","52.5","315","21"],"correct_option":0,"difficulty":"medium","explanation":"LCM = (15 × 21) ÷ HCF(3) = 105.","sort_order":10}]$json$),
  ('mathematics', "1.2", null, "Fractions, decimals, percentages, ordering and operations — Core Paper 1 (non-calculator)", $json$[{"question_text":"Write 6/7 in its simplest form.","options":["6/7","7/6","12/14","7/8"],"correct_option":0,"difficulty":"medium","explanation":"Divide numerator and denominator by 1.","sort_order":1},{"question_text":"Work out 15% of 80.","options":["65","1.2","12","120"],"correct_option":2,"difficulty":"medium","explanation":"15% of 80 = 15/100 × 80 = 12.","sort_order":2},{"question_text":"Work out 8/6 + 6/5 in simplest form (answer as fraction).","options":["76/30","48/30","14/11","4/30"],"correct_option":0,"difficulty":"medium","explanation":"Common denominator 30: (40 + 36)/30.","sort_order":3},{"question_text":"Write 8/11 in its simplest form.","options":["16/22","11/8","8/11","9/12"],"correct_option":2,"difficulty":"medium","explanation":"Divide numerator and denominator by 1.","sort_order":4},{"question_text":"Work out 25% of 60.","options":["35","150","15","1.5"],"correct_option":2,"difficulty":"medium","explanation":"25% of 60 = 25/100 × 60 = 15.","sort_order":5},{"question_text":"Work out 5/6 + 7/2 in simplest form (answer as fraction).","options":["-32/12","52/12","12/8","35/12"],"correct_option":1,"difficulty":"medium","explanation":"Common denominator 12: (10 + 42)/12.","sort_order":6},{"question_text":"Write 8/13 in its simplest form.","options":["16/26","9/14","13/8","8/13"],"correct_option":3,"difficulty":"medium","explanation":"Divide numerator and denominator by 1.","sort_order":7},{"question_text":"Work out 10% of 80.","options":["0.8","70","80","8"],"correct_option":3,"difficulty":"medium","explanation":"10% of 80 = 10/100 × 80 = 8.","sort_order":8},{"question_text":"Work out 8/7 + 6/2 in simplest form (answer as fraction).","options":["58/14","14/9","48/14","-26/14"],"correct_option":0,"difficulty":"medium","explanation":"Common denominator 14: (16 + 42)/14.","sort_order":9},{"question_text":"Write 6/8 in its simplest form.","options":["4/3","7/9","3/4","12/16"],"correct_option":2,"difficulty":"medium","explanation":"Divide numerator and denominator by 2.","sort_order":10}]$json$),
  ('mathematics', "1.3", null, "Indices and standard form — Core Paper 1 (non-calculator)", $json$[{"question_text":"Simplify (4x^4) × (4x^4).","options":["16x^8","8x^8","16x^16","16x^0"],"correct_option":0,"difficulty":"medium","explanation":"Multiply coefficients (4×4=16) and add indices (4+4=8).","sort_order":1},{"question_text":"Write 40 as 2 to a power × 5. What power is needed?","options":["3","4","2","6"],"correct_option":0,"difficulty":"medium","explanation":"2^3 = 8, and 8 × 5 = 40.","sort_order":2},{"question_text":"A number in standard form is A × 10^n with 1 ≤ A < 10. Which n suits 700 000?","options":["4","6","7","5"],"correct_option":3,"difficulty":"medium","explanation":"700 000 = 7 × 10^5.","sort_order":3},{"question_text":"Simplify (2x^2) × (2x^4).","options":["4x^-2","4x^8","4x^6 (check)","4x^6"],"correct_option":3,"difficulty":"medium","explanation":"Multiply coefficients (2×2=4) and add indices (2+4=6).","sort_order":4},{"question_text":"Write 500 as 5 to a power × 4. What power is needed?","options":["2","6","4","3"],"correct_option":3,"difficulty":"medium","explanation":"5^3 = 125, and 125 × 4 = 500.","sort_order":5},{"question_text":"A number in standard form is A × 10^n with 1 ≤ A < 10. Which n suits 300 000?","options":["5","4","7","6"],"correct_option":0,"difficulty":"medium","explanation":"300 000 = 3 × 10^5.","sort_order":6},{"question_text":"Simplify (5x^2) × (5x^3).","options":["25x^-1","10x^5","25x^6","25x^5"],"correct_option":3,"difficulty":"medium","explanation":"Multiply coefficients (5×5=25) and add indices (2+3=5).","sort_order":7},{"question_text":"Write 63 as 3 to a power × 7. What power is needed?","options":["1","2","3","4"],"correct_option":1,"difficulty":"medium","explanation":"3^2 = 9, and 9 × 7 = 63.","sort_order":8},{"question_text":"Simplify (2x^5) × (2x^3).","options":["4x^8","4x^15","4x^8 (check)","4x^2"],"correct_option":0,"difficulty":"medium","explanation":"Multiply coefficients (2×2=4) and add indices (5+3=8).","sort_order":9},{"question_text":"Write 375 as 5 to a power × 3. What power is needed?","options":["3","6","2","4"],"correct_option":0,"difficulty":"medium","explanation":"5^3 = 125, and 125 × 3 = 375.","sort_order":10}]$json$),
  ('mathematics', "1.4", null, "Estimation, rounding and bounds — Core Paper 1 (non-calculator)", $json$[{"question_text":"A length is 5 cm to the nearest 0.1 cm. What is its upper bound?","options":["5.15","5.1 (check)","5","5.1"],"correct_option":3,"difficulty":"medium","explanation":"Upper bound = 5 + 0.05 = 5.1.","sort_order":1},{"question_text":"Round 913 to 2 significant figures.","options":["913","910","920","900"],"correct_option":1,"difficulty":"medium","explanation":"The second significant figure is the tens digit: 910.","sort_order":2},{"question_text":"A length is 3.9 cm to the nearest 0.1 cm. What is its upper bound?","options":["4 (check)","4","3.9","4.05"],"correct_option":1,"difficulty":"medium","explanation":"Upper bound = 3.9 + 0.05 = 4.","sort_order":3},{"question_text":"Round 687 to 2 significant figures.","options":["701","687","700","690"],"correct_option":3,"difficulty":"medium","explanation":"The second significant figure is the tens digit: 690.","sort_order":4},{"question_text":"A length is 5.3 cm to the nearest 0.1 cm. What is its upper bound?","options":["5.3","5.4","5.4 (check)","5.45"],"correct_option":1,"difficulty":"medium","explanation":"Upper bound = 5.3 + 0.05 = 5.4.","sort_order":5},{"question_text":"Round 664 to 2 significant figures.","options":["700","670","664","660"],"correct_option":3,"difficulty":"medium","explanation":"The second significant figure is the tens digit: 660.","sort_order":6},{"question_text":"A length is 7.4 cm to the nearest 0.1 cm. What is its upper bound?","options":["7.4","7.5","7.5 (check)","7.55"],"correct_option":1,"difficulty":"medium","explanation":"Upper bound = 7.4 + 0.05 = 7.5.","sort_order":7},{"question_text":"Round 896 to 2 significant figures.","options":["900","901","910","896"],"correct_option":0,"difficulty":"medium","explanation":"The second significant figure is the tens digit: 900.","sort_order":8},{"question_text":"A length is 3.6 cm to the nearest 0.1 cm. What is its upper bound?","options":["3.7 (check)","3.75","3.7","3.6"],"correct_option":2,"difficulty":"medium","explanation":"Upper bound = 3.6 + 0.05 = 3.7.","sort_order":9},{"question_text":"Round 939 to 2 significant figures.","options":["900","950","939","940"],"correct_option":3,"difficulty":"medium","explanation":"The second significant figure is the tens digit: 940.","sort_order":10}]$json$),
  ('mathematics', "1.5", null, "Ratio, proportion, rates and percentages — Core Paper 1 (non-calculator)", $json$[{"question_text":"Divide $120 in the ratio 2:5. What is the larger share?","options":["85.714","34.286","17.143","34.286"],"correct_option":0,"difficulty":"medium","explanation":"120 ÷ 7 parts = $17.143 per part; larger = 5 parts.","sort_order":1},{"question_text":"A price increases by 25% from $120. What is the new price?","options":["30","145","90","150"],"correct_option":3,"difficulty":"medium","explanation":"Multiplier 1.25: 120 × 1.25 = 150.","sort_order":2},{"question_text":"Divide $90 in the ratio 2:5. What is the larger share?","options":["64.286","25.714","12.857","25.714"],"correct_option":0,"difficulty":"medium","explanation":"90 ÷ 7 parts = $12.857 per part; larger = 5 parts.","sort_order":3},{"question_text":"A price increases by 25% from $40. What is the new price?","options":["30","10","65","50"],"correct_option":3,"difficulty":"medium","explanation":"Multiplier 1.25: 40 × 1.25 = 50.","sort_order":4},{"question_text":"Divide $90 in the ratio 1:4. What is the larger share?","options":["72","21","18","19"],"correct_option":0,"difficulty":"medium","explanation":"90 ÷ 5 parts = $18 per part; larger = 4 parts.","sort_order":5},{"question_text":"Divide $60 in the ratio 5:7. What is the larger share?","options":["26","35","5","25"],"correct_option":1,"difficulty":"medium","explanation":"60 ÷ 12 parts = $5 per part; larger = 7 parts.","sort_order":6},{"question_text":"A price increases by 50% from $120. What is the new price?","options":["61","60","180","170"],"correct_option":2,"difficulty":"medium","explanation":"Multiplier 1.50: 120 × 1.5 = 180.","sort_order":7},{"question_text":"Divide $84 in the ratio 3:4. What is the larger share?","options":["48","12","36","37"],"correct_option":0,"difficulty":"medium","explanation":"84 ÷ 7 parts = $12 per part; larger = 4 parts.","sort_order":8},{"question_text":"A price increases by 20% from $80. What is 