  ('mathematics', "2.1", null, "Algebraic language, manipulation and fractions — Core Paper 1 (non-calculator)", $json$[{"question_text":"Expand 6(x + 4) − 3x.","options":["3x − 24","9x + 24","6x + 21","3x + 24"],"correct_option":3,"difficulty":"medium","explanation":"6x + 24 − 3x = 3x + 24.","sort_order":1},{"question_text":"Factorise x² + 13x + 36.","options":["(x + 4)(x + 9)","(x + 36)(x + 1)","(x − 4)(x − 9)","(x + 4)(x − 9)"],"correct_option":0,"difficulty":"medium","explanation":"4 + 9 = 13 and 4 × 9 = 36.","sort_order":2},{"question_text":"Expand 5(x + 6) − 5x.","options":["5x + 25","0x − 30","10x + 30","0x + 30"],"correct_option":3,"difficulty":"medium","explanation":"5x + 30 − 5x = 0x + 30.","sort_order":3},{"question_text":"Factorise x² + 10x + 24.","options":["(x + 24)(x + 1)","(x + 6)(x + 4)","(x − 6)(x − 4)","(x + 6)(x − 4)"],"correct_option":1,"difficulty":"medium","explanation":"6 + 4 = 10 and 6 × 4 = 24.","sort_order":4},{"question_text":"Expand 4(x + 3) − 3x.","options":["1x − 12","7x + 12","4x + 9","1x + 12"],"correct_option":3,"difficulty":"medium","explanation":"4x + 12 − 3x = 1x + 12.","sort_order":5},{"question_text":"Factorise x² + 14x + 48.","options":["(x + 48)(x + 1)","(x + 6)(x + 8)","(x − 6)(x − 8)","(x + 6)(x − 8)"],"correct_option":1,"difficulty":"medium","explanation":"6 + 8 = 14 and 6 × 8 = 48.","sort_order":6},{"question_text":"Expand 3(x + 7) − 4x.","options":["7x + 21","3x + 17","-1x − 21","-1x + 21"],"correct_option":3,"difficulty":"medium","explanation":"3x + 21 − 4x = -1x + 21.","sort_order":7},{"question_text":"Factorise x² + 9x + 20.","options":["(x + 20)(x + 1)","(x + 4)(x + 5)","(x + 4)(x − 5)","(x − 4)(x − 5)"],"correct_option":1,"difficulty":"medium","explanation":"4 + 5 = 9 and 4 × 5 = 20.","sort_order":8},{"question_text":"Expand 3(x + 2) − 3x.","options":["0x + 6","3x + 3","6x + 6","0x − 6"],"correct_option":0,"difficulty":"medium","explanation":"3x + 6 − 3x = 0x + 6.","sort_order":9},{"question_text":"Factorise x² + 11x + 30.","options":["(x + 5)(x − 6)","(x − 5)(x − 6)","(x + 5)(x + 6)","(x + 30)(x + 1)"],"correct_option":2,"difficulty":"medium","explanation":"5 + 6 = 11 and 5 × 6 = 30.","sort_order":10}]$json$),
  ('mathematics', "2.2", null, "Equations and rearranging formulae — Core Paper 1 (non-calculator)", $json$[{"question_text":"Solve 7x + 19 = 68.","options":["8.5","7","8","6"],"correct_option":1,"difficulty":"medium","explanation":"7x = 68 − 19 = 49, so x = 7.","sort_order":1},{"question_text":"Make x the subject: y = 3x − 7. What is x?","options":["(y + 7)/3","(y − 7)/3","y/3 + 7","3y + 7"],"correct_option":0,"difficulty":"medium","explanation":"y + 7 = 3x, so x = (y + 7)/3.","sort_order":2},{"question_text":"Solve 3x + 12 = 21.","options":["3","2","4","5.25"],"correct_option":0,"difficulty":"medium","explanation":"3x = 21 − 12 = 9, so x = 3.","sort_order":3},{"question_text":"Make x the subject: y = 5x − 6. What is x?","options":["y/5 + 6","5y + 6","(y + 6)/5","(y − 6)/5"],"correct_option":2,"difficulty":"medium","explanation":"y + 6 = 5x, so x = (y + 6)/5.","sort_order":4},{"question_text":"Solve 3x + 20 = 32.","options":["5","8","3","4"],"correct_option":3,"difficulty":"medium","explanation":"3x = 32 − 20 = 12, so x = 4.","sort_order":5},{"question_text":"Make x the subject: y = 3x − 4. What is x?","options":["3y + 4","(y + 4)/3","(y − 4)/3","y/3 + 4"],"correct_option":1,"difficulty":"medium","explanation":"y + 4 = 3x, so x = (y + 4)/3.","sort_order":6},{"question_text":"Solve 2x + 2 = 12.","options":["4","6","5","7"],"correct_option":2,"difficulty":"medium","explanation":"2x = 12 − 2 = 10, so x = 5.","sort_order":7},{"question_text":"Make x the subject: y = 2x − 9. What is x?","options":["(y − 9)/2","2y + 9","y/2 + 9","(y + 9)/2"],"correct_option":3,"difficulty":"medium","explanation":"y + 9 = 2x, so x = (y + 9)/2.","sort_order":8},{"question_text":"Solve 7x + 2 = 37.","options":["5","6","4.625","4"],"correct_option":0,"difficulty":"medium","explanation":"7x = 37 − 2 = 35, so x = 5.","sort_order":9},{"question_text":"Make x the subject: y = 4x − 4. What is x?","options":["y/4 + 4","4y + 4","(y − 4)/4","(y + 4)/4"],"correct_option":3,"difficulty":"medium","explanation":"y + 4 = 4x, so x = (y + 4)/4.","sort_order":10}]$json$),
  ('mathematics', "2.3", null, "Inequalities and sequences — Core Paper 1 (non-calculator)", $json$[{"question_text":"Solve the inequality 3x > 96 and pick the correct solution.","options":["x > 32","x < 32","x > 96","x < 96"],"correct_option":0,"difficulty":"medium","explanation":"Divide both sides by 3 (positive, so the sign stays): x > 32.","sort_order":1},{"question_text":"Solve the inequality 4x > 92 and pick the correct solution.","options":["x > 23","x < 23","x > 92","x < 92"],"correct_option":0,"difficulty":"medium","explanation":"Divide both sides by 4 (positive, so the sign stays): x > 23.","sort_order":2},{"question_text":"Solve the inequality 3x > 99 and pick the correct solution.","options":["x > 33","x < 33","x > 99","x < 99"],"correct_option":0,"difficulty":"medium","explanation":"Divide both sides by 3 (positive, so the sign stays): x > 33.","sort_order":3},{"question_text":"Solve the inequality 9x > 288 and pick the correct solution.","options":["x > 32","x < 32","x > 288","x < 288"],"correct_option":0,"difficulty":"medium","explanation":"Divide both sides by 9 (positive, so the sign stays): x > 32.","sort_order":4},{"question_text":"Solve the inequality 8x > 288 and pick the correct solution.","options":["x > 36","x < 36","x > 288","x < 288"],"correct_option":0,"difficulty":"medium","explanation":"Divide both sides by 8 (positive, so the sign stays): x > 36.","sort_order":5},{"question_text":"Solve the inequality 9x > 171 and pick the correct solution.","options":["x > 19","x < 19","x > 171","x < 171"],"correct_option":0,"difficulty":"medium","explanation":"Divide both sides by 9 (positive, so the sign stays): x > 19.","sort_order":6},{"question_text":"Solve the inequality 5x > 195 and pick the correct solution.","options":["x > 39","x < 39","x > 195","x < 195"],"correct_option":0,"difficulty":"medium","explanation":"Divide both sides by 5 (positive, so the sign stays): x > 39.","sort_order":7},{"question_text":"Solve the inequality 2x > 62 and pick the correct solution.","options":["x > 31","x < 31","x > 62","x < 62"],"correct_option":0,"difficulty":"medium","explanation":"Divide both sides by 2 (positive, so the sign stays): x > 31.","sort_order":8},{"question_text":"Solve the inequality 3x > 87 and pick the correct solution.","options":["x > 29","x < 29","x > 87","x < 87"],"correct_option":0,"difficulty":"medium","explanation":"Divide both sides by 3 (positive, so the sign stays): x > 29.","sort_order":9},{"question_text":"Solve the inequality 8x > 112 and pick the correct solution.","options":["x > 14","x < 14","x > 112","x < 112"],"correct_option":0,"difficulty":"medium","explanation":"Divide both sides by 8 (positive, so the sign stays): x > 14.","sort_order":10}]$json$),
  ('mathematics', "2.4", null, "Practical graphs, function graphs and sketches — Core Paper 1 (non-calculator)", $json$[{"question_text":"The line y = 4x + 2 crosses the y-axis at which point?","options":["(0, 2)","(2, 0)","(0, 4)","(4, 0)"],"correct_option":0,"difficulty":"medium","explanation":"At x = 0, y = c, so the intercept is (0, 2).","sort_order":1},{"question_text":"The line y = 3x − 3 crosses the y-axis at which point?","options":["(0, -3)","(-3, 0)","(0, 3)","(3, 0)"],"correct_option":0,"difficulty":"medium","explanation":"At x = 0, y = c, so the intercept is (0, -3).","sort_order":2},{"question_text":"The line y = 4x − 2 crosses the y-axis at which point?","options":["(0, -2)","(-2, 0)","(0, 4)","(4, 0)"],"correct_option":0,"difficulty":"medium","explanation":"At x = 0, y = c, so the intercept is (0, -2).","sort_order":3},{"question_text":"The line y = 4x + 6 crosses the y-axis at which point?","options":["(0, 6)","(6, 0)","(0, 4)","(4, 0)"],"correct_option":0,"difficulty":"medium","explanation":"At x = 0, y = c, so the intercept is (0, 6).","sort_order":4},{"question_text":"The line y = 2x − 3 crosses the y-axis at which point?","options":["(0, -3)","(-3, 0)","(0, 2)","(2, 0)"],"correct_option":0,"difficulty":"medium","explanation":"At x = 0, y = c, so the intercept is (0, -3).","sort_order":5},{"question_text":"The line y = 2x + 2 crosses the y-axis at which point?","options":["(0, 2)","(2, 0)","(0, 2)","(2, 0)"],"correct_option":0,"difficulty":"medium","explanation":"At x = 0, y = c, so the intercept is (0, 2).","sort_order":6},{"question_text":"The line y = 5x − 3 crosses the y-axis at which point?","options":["(0, -3)","(-3, 0)","(0, 5)","(5, 0)"],"correct_option":0,"difficulty":"medium","explanation":"At x = 0, y = c, so the intercept is (0, -3).","sort_order":7},{"question_text":"The line y = 5x − 1 crosses the y-axis at which point?","options":["(0, -1)","(-1, 0)","(0, 5)","(5, 0)"],"correct_option":0,"difficulty":"medium","explanation":"At x = 0