  ('mathematics', "3.1", null, "Coordinates, gradients, distance and midpoint — Core Paper 1 (non-calculator)", $json$[{"question_text":"Find the distance between (-3, 1) and (0, 6).","options":["5.831","15","2","8"],"correct_option":0,"difficulty":"medium","explanation":"√(3² + 5²) = √34 ≈ 5.831.","sort_order":1},{"question_text":"Find the midpoint of (-1, -3) and (3, 2).","options":["(1, -0.5)","(2, 2.5)","(3, 2)","(-1, -3)"],"correct_option":0,"difficulty":"medium","explanation":"Average each coordinate: ((-1+3)/2, (-3+2)/2).","sort_order":2},{"question_text":"Find the distance between (0, 3) and (5, 9).","options":["30","7.81","1","11"],"correct_option":1,"difficulty":"medium","explanation":"√(5² + 6²) = √61 ≈ 7.81.","sort_order":3},{"question_text":"Find the midpoint of (3, -2) and (8, -1).","options":["(2.5, 0.5)","(3, -2)","(8, -1)","(5.5, -1.5)"],"correct_option":3,"difficulty":"medium","explanation":"Average each coordinate: ((3+8)/2, (-2+-1)/2).","sort_order":4},{"question_text":"Find the distance between (3, -3) and (5, -1).","options":["4 (check)","0","2.828","4"],"correct_option":2,"difficulty":"medium","explanation":"√(2² + 2²) = √8 ≈ 2.828.","sort_order":5},{"question_text":"Find the midpoint of (-1, -4) and (1, -3).","options":["(1, 0.5)","(1, -3)","(0, -3.5)","(-1, -4)"],"correct_option":2,"difficulty":"medium","explanation":"Average each coordinate: ((-1+1)/2, (-4+-3)/2).","sort_order":6},{"question_text":"Find the distance between (-4, -4) and (-2, 2).","options":["12","8","6.325","4"],"correct_option":2,"difficulty":"medium","explanation":"√(2² + 6²) = √40 ≈ 6.325.","sort_order":7},{"question_text":"Find the midpoint of (0, -1) and (1, 0).","options":["(0.5, -0.5)","(0, -1)","(0.5, 0.5)","(1, 0)"],"correct_option":0,"difficulty":"medium","explanation":"Average each coordinate: ((0+1)/2, (-1+0)/2).","sort_order":8},{"question_text":"Find the distance between (1, 0) and (3, 5).","options":["5.385","10","3","7"],"correct_option":0,"difficulty":"medium","explanation":"√(2² + 5²) = √29 ≈ 5.385.","sort_order":9},{"question_text":"Find the midpoint of (1, -3) and (2, 1).","options":["(0.5, 2)","(1.5, -1)","(2, 1)","(1, -3)"],"correct_option":1,"difficulty":"medium","explanation":"Average each coordinate: ((1+2)/2, (-3+1)/2).","sort_order":10}]$json$),
  ('mathematics', "5.1", null, "Units, perimeter and area — Core Paper 1 (non-calculator)", $json$[{"question_text":"A rectangle is 6 cm by 5 cm. Its area is:","options":["24","11","22","30"],"correct_option":3,"difficulty":"medium","explanation":"Area = 6 × 5 = 30 cm².","sort_order":1},{"question_text":"A rectangle is 4 cm by 4 cm. Its area is:","options":["16","8","17","18"],"correct_option":0,"difficulty":"medium","explanation":"Area = 4 × 4 = 16 cm².","sort_order":2},{"question_text":"A rectangle is 3 cm by 5 cm. Its area is:","options":["15","8","18","16"],"correct_option":0,"difficulty":"medium","explanation":"Area = 3 × 5 = 15 cm².","sort_order":3},{"question_text":"A rectangle is 7 cm by 4 cm. Its area is:","options":["28","22","11","24"],"correct_option":0,"difficulty":"medium","explanation":"Area = 7 × 4 = 28 cm².","sort_order":4},{"question_text":"A rectangle is 6 cm by 9 cm. Its area is:","options":["54","32","30","15"],"correct_option":0,"difficulty":"medium","explanation":"Area = 6 × 9 = 54 cm².","sort_order":5},{"question_text":"A rectangle is 5 cm by 9 cm. Its area is:","options":["14","28","30","45"],"correct_option":3,"difficulty":"medium","explanation":"Area = 5 × 9 = 45 cm².","sort_order":6},{"question_text":"A rectangle is 10 cm by 4 cm. Its area is:","options":["40","28","14","30"],"correct_option":0,"difficulty":"medium","explanation":"Area = 10 × 4 = 40 cm².","sort_order":7},{"question_text":"A rectangle is 3 cm by 10 cm. Its area is:","options":["28","13","26","30"],"correct_option":3,"difficulty":"medium","explanation":"Area = 3 × 10 = 30 cm².","sort_order":8},{"question_text":"A rectangle is 5 cm by 12 cm. Its area is:","options":["60","34","36","17"],"correct_option":0,"difficulty":"medium","explanation":"Area = 5 × 12 = 60 cm².","sort_order":9},{"question_text":"A rectangle is 7 cm by 5 cm. Its area is:","options":["12","35","24","26"],"correct_option":1,"difficulty":"medium","explanation":"Area = 7 × 5 = 35 cm².","sort_order":10}]$json$