  ('mathematics', "9.1", null, "Data, averages and displays — Core Paper 1 (non-calculator)", $json$[{"question_text":"Find the mean of 9, 2, 7, 9, 5.","options":["7 (check)","7","32","6.4"],"correct_option":3,"difficulty":"medium","explanation":"Sum 32 ÷ 5 = 6.4.","sort_order":1},{"question_text":"Find the median of 6, 2, 1, 5, 4, 7, 3.","options":["4 (check)","4","3","5"],"correct_option":1,"difficulty":"medium","explanation":"Ordered: 1, 2, 3, 4, 5, 6, 7; middle value is 4.","sort_order":2},{"question_text":"Find the mean of 4, 3, 9, 3, 9.","options":["4","28","6","5.6"],"correct_option":3,"difficulty":"medium","explanation":"Sum 28 ÷ 5 = 5.6.","sort_order":3},{"question_text":"Find the median of 1, 5, 6, 3, 4, 2.","options":["3.5","5","4","3"],"correct_option":2,"difficulty":"medium","explanation":"Ordered: 1, 2, 3, 4, 5, 6; middle value is 4.","sort_order":4},{"question_text":"Find the mean of 3, 4, 2, 2, 8.","options":["6","3.8","3","19"],"correct_option":1,"difficulty":"medium","explanation":"Sum 19 ÷ 5 = 3.8.","sort_order":5},{"question_text":"Find the median of 2, 6, 3, 4, 5, 1.","options":["3.5","3","4","5"],"correct_option":2,"difficulty":"medium","explanation":"Ordered: 1, 2, 3, 4, 5, 6; middle value is 4.","sort_order":6},{"question_text":"Find the mean of 5, 2, 3, 9, 4.","options":["4.6","4","23","7"],"correct_option":0,"difficulty":"medium","explanation":"Sum 23 ÷ 5 = 4.6.","sort_order":7},{"question_text":"Find the median of 1, 4, 3, 6, 7, 5, 2.","options":["5","4 (check)","3","4"],"correct_option":3,"difficulty":"medium","explanation":"Ordered: 1, 2, 3, 4, 5, 6, 7; middle value is 4.","sort_order":8},{"question_text":"Find the mean of 5, 3, 6, 9, 9.","options":["6 (check)","6.4","32","6"],"correct_option":1,"difficulty":"medium","explanation":"Sum 32 ÷ 5 = 6.4.","sort_order":9},{"question_text":"Find the median of 2, 5, 3, 4, 1.","options":["4","3","3 (check)","2"],"correct_option":1,"difficulty":"medium","explanation":"Ordered: 1, 2, 3, 4, 5; middle value is 3.","sort_order":10}]$json$),
  ('mathematics', "1.1", null, "Types of number, sets, powers and roots — Core Paper 3 (calculator)", $json$[{"question_text":"Find the HCF of 18 and 22.","options":["7","2","4","5"],"correct_option":1,"difficulty":"medium","explanation":"Common factors of 18 and 22 give HCF = 2.","sort_order":1},{"question_text":"Find the LCM of 15 and 21.","options":["315","105","52.5","21"],"correct_option":1,"difficulty":"medium","explanation":"LCM = (15 × 21) ÷ HCF(3) = 105.","sort_order":2},{"question_text":"Find the HCF of 8 and 14.","options":["6","4","5","2"],"correct_option":3,"difficulty":"medium","explanation":"Common factors of 8 and 14 give HCF = 2.","sort_order":3},{"question_text":"Find the LCM of 15 and 18.","options":["45","270","90","18"],"correct_option":2,"difficulty":"medium","explanation":"LCM = (15 × 18) ÷ HCF(3) = 90.","sort_order":4},{"question_text":"Find the HCF of 8 and 12.","options":["6","4","8","5"],"correct_option":1,"difficulty":"medium","explanation":"Common factors of 8 and 12 give HCF = 4.","sort_order":5},{"question_text":"Find the LCM of 10 and 16.","options":["16","40","160","80"],"correct_option":3,"difficulty":"medium","explanation":"LCM = (10 × 16) ÷ HCF(2) = 80.","sort_order":6},{"question_text":"Find the HCF of 48 and 52.","options":["8","5","4","6"],"correct_option":2,"difficulty":"medium","explanation":"Common factors of 48 and 52 give HCF = 4.","sort_order":7},{"question_text":"Find the LCM of 10 and 14.","options":["70","35","14","140"],"correct_option":0,"difficulty":"medium","explanation":"LCM = (10 × 14) ÷ HCF(2) = 70.","sort_order":8},{"question_text":"Find the HCF of 30 and 34.","options":["2","5","7","4"],"correct_option":0,"difficulty":"medium","explanation":"Common factors of 30 and 34 give HCF = 2.","sort_order":9},{"question_text":"Find the HCF of 12 and 24.","options":["13","24","14","12"],"correct_option":3,"difficulty":"medium","explanation":"Common factors of 12 and 24 give HCF = 12.","sort_order":10}]$json$),
  ('mathematics', "1.2", null, "Fractions, decimals, percentages, ordering and operations — Core Paper 3 (calculator)", $json$[{"question_text":"Write 3/7 in its simplest form.","options":["4/8","6/14","3/7","7/3"],"correct_option":2,"difficulty":"medium","explanation":"Divide numerator and denominator by 1.","sort_order":1},{"question_text":"Work out 15% of 120.","options":["180","18","1.8","105"],"correct_option":1,"difficulty":"medium","explanation":"15% of 120 = 15/100 × 120 = 18.","sort_order":2},{"question_text":"Work out 5/9 + 8/4 in simplest form (answer as fraction).","options":["13/13","-52/36","92/36","40/36"],"correct_option":2,"difficulty":"medium","explanation":"Common denominator 36: (20 + 72)/36.","sort_order":3},{"question_text":"Write 6/9 in its simplest form.","options":["7/10","12/18","3/2","2/3"],"correct_option":3,"difficulty":"medium","explanation":"Divide numerator and denominator by 3.","sort_order":4},{"question_text":"Work out 40% of 40.","options":["16","1.6","160","0"],"correct_option":0,"difficulty":"medium","explanation":"40% of 40 = 40/100 × 40 = 16.","sort_order":5},{"question_text":"Work out 8/4 + 9/6 in simplest form (answer as fraction).","options":["17/10","72/24","12/24","84/24"],"correct_option":3,"difficulty":"medium","explanation":"Common denominator 24: (48 + 36)/24.","sort_order":6},{"question_text":"Write 8/9 in its simplest form.","options":["9/8","8/9","9/10","16/18"],"correct_option":1,"difficulty":"medium","explanation":"Divide numerator and denominator by 1.","sort_order":7},{"question_text":"Work out 25% of 60.","options":["35","15","1.5","150"],"correct_option":1,"difficulty":"medium","explanation":"25% of 60 = 25/100 × 60 = 15.","sort_order":8},{"question_text":"Work out 4/3 + 8/4 in simplest form (answer as fraction).","options":["40/12","-8/12","12/7","32/12"],"correct_option":0,"difficulty":"medium","explanation":"Common denominator 12: (16 + 24)/12.","sort_order":9},{"question_text":"Write 6/8 in its simplest form.","options":["3/4","4/3","7/9","12/16"],"correct_option":0,"difficulty":"medium","explanation":"Divide numerator and denominator by 2.","sort_order":10}]$json$),
  ('mathematics', "1.3", null, "Indices and standard form — Core Paper 3 (calculator)", $json$[{"question_text":"Simplify (5x^5) × (5x^2).","options":["10x^7","25x^10","25x^7","25x^3"],"correct_option":2,"difficulty":"medium","explanation":"Multiply coefficients (5×5=25) and add indices (5+2=7).","sort_order":1},{"question_text":"Write 1792 as 4 to a power × 7. What power is needed?","options":["3","4","5","8"],"correct_option":1,"difficulty":"medium","explanation":"4^4 = 256, and 256 × 7 = 1792.","sort_order":2},{"question_text":"A number in standard form is A × 10^n with 1 ≤ A < 10. Which n suits 800 000?","options":["5","7","4","6"],"correct_option":0,"difficulty":"medium","explanation":"800 000 = 8 × 10^5.","sort_order":3},{"question_text":"Simplify (4x^2) × (4x^2).","options":["16x^4 (check)","16x^0","8x^4","16x^4"],"correct_option":3,"difficulty":"medium","explanation":"Multiply coefficients (4×4=16) and add indices (2+2=4).","sort_order":4},{"question_text":"Write 2048 as 4 to a power × 8. What power is needed?","options":["4","8","5","3"],"correct_option":0,"difficulty":"medium","explanation":"4^4 = 256, and 256 × 8 = 2048.","sort_order":5},{"question_text":"A number in standard form is A × 10^n with 1 ≤ A < 10. Which n suits 400 000?","options":["5","6","7","4"],"correct_option":0,"difficulty":"medium","explanation":"400 000 = 4 × 10^5.","sort_order":6},{"question_text":"Simplify (5x^4) × (5x^3).","options":["25x^12","25x^7","25x^1","10x^7"],"correct_option":1,"difficulty":"medium","explanation":"Multiply coefficients (5×5=25) and add indices (4+3=7).","sort_order":7},{"question_text":"Write 5625 as 5 to a power × 9. What power is needed?","options":["8","5","4","3"],"correct_option":2,"difficulty":"medium","explanation":"5^4 = 625, and 625 × 9 = 5625.","sort_order":8},{"question_text":"Simplify (5x^2) × (5x^3).","options":["10x^5","25x^-1","25x^6","25x^5"],"correct_option":3,"difficulty":"medium","explanation":"Multiply coefficients (5×5=25) and add indices (2+3=5).","sort_order":9},{"question_text":"Write 1536 as 4 to a power × 6. What power is needed?","options":["8","5","4","3"],"correct_option":2,"difficulty":"medium","explanation":"4^4 = 256, and 256 × 6 = 1536.","sort_order":10}]$json$),
  ('mathematics', "1.4", null, "Estimation, rounding and bounds — Core Paper 3 (calculator)", $json$[{"question_text":"A length is 6.3 cm to the nearest 0.1 cm. What is its upper bound?","options":["6.45","6.4","6.4 (check)","6.3"],"correct_option":1,"difficulty":"medium","explanation":"Upper bound = 6.3 + 0.05 = 6.4.","sort_order":1},{"question_text":"Round 841 to 2 significant figures.","options":["800","840","841","850"],"correct_option":1,"difficulty":"medium","explanation":"The second significant figure is the tens digit: 840.","sort_order":2},{"question_text":"Round 681 to 2 significant figures.","options":["680","681","700","690"],"correct_option":0,"difficulty":"medium","explanation":"The second significant figure is the tens digit: 680.","sort_order":3},{"question_text":"A length is 6.1 cm to the nearest 0.1 cm. What is its upper bound?","options":["6.2 (check)","6.1","6.2","6.25"],"correct_option":2,"difficulty":"medium","explanation":"Upper bound = 6.1 + 0.05 = 6.2.","sort_order":4},{"question_text":"Round 724 to 2 significant figures.","options":["730","700","720","724"],"correct_option":2,"difficulty":"medium","explanation":"The second significant figure is the tens digit: 720.","sort_order":5},{"question_text":"A length is 7.5 cm to the nearest 0.1 cm. What is its upper bound?","options":["7.6","7.6 (check)","7.5","7.65"],"correct_option":0,"difficulty":"medium","explanation":"Upper bound = 7.5 + 0.05 = 7.6.","sort_order":6},{"question_text":"Round 713 to 2 significant figures.","options":["700","710","720","713"],"correct_option":1,"difficulty":"medium","explanation":"The second significant figure is the tens digit: 710.","sort_order":7},{"question_text":"A length is 0.4 cm to the nearest 0.1 cm. What is its upper bound?","options":["0.55","0.4","0.5","0.5 (check)"],"correct_option":2,"difficulty":"medium","explanation":"Upper bound = 0.4 + 0.05 = 0.5.","sort_order":8},{"question_text":"Round 768 to 2 significant figures.","options":["780","800","768"