  ('mathematics', "1.5", null, "Ratio, proportion, rates and percentages — Core Paper 3 (calculator)", $json$[{"question_text":"Divide $120 in the ratio 5:7. What is the larger share?","options":["70","50","10","51"],"correct_option":0,"difficulty":"medium","explanation":"120 ÷ 12 parts = $10 per part; larger = 7 parts.","sort_order":1},{"question_text":"A price increases by 50% from $120. What is the new price?","options":["180","170","61","60"],"correct_option":0,"difficulty":"medium","explanation":"Multiplier 1.50: 120 × 1.5 = 180.","sort_order":2},{"question_text":"Divide $84 in the ratio 3:4. What is the larger share?","options":["37","36","12","48"],"correct_option":3,"difficulty":"medium","explanation":"84 ÷ 7 parts = $12 per part; larger = 4 parts.","sort_order":3},{"question_text":"A price increases by 10% from $80. What is the new price?","options":["8","90","72","88"],"correct_option":3,"difficulty":"medium","explanation":"Multiplier 1.10: 80 × 1.1 = 88.","sort_order":4},{"question_text":"Divide $60 in the ratio 3:4. What is the larger share?","options":["34.286","25.714","26.714","8.571"],"correct_option":0,"difficulty":"medium","explanation":"60 ÷ 7 parts = $8.571 per part; larger = 4 parts.","sort_order":5},{"question_text":"A price increases by 25% from $120. What is the new price?","options":["145","90","30","150"],"correct_option":3,"difficulty":"medium","explanation":"Multiplier 1.25: 120 × 1.25 = 150.","sort_order":6},{"question_text":"Divide $90 in the ratio 3:4. What is the larger share?","options":["39.571","51.429","12.857","38.571"],"correct_option":1,"difficulty":"medium","explanation":"90 ÷ 7 parts = $12.857 per part; larger = 4 parts.","sort_order":7},{"question_text":"A price increases by 50% from $80. What is the new price?","options":["130","120","41","40"],"correct_option":1,"difficulty":"medium","explanation":"Multiplier 1.50: 80 × 1.5 = 120.","sort_order":8},{"question_text":"Divide $60 in the ratio 2:5. What is the larger share?","options":["42.857","17.143","8.571","17.143"],"correct_option":0,"difficulty":"medium","explanation":"60 ÷ 7 parts = $8.571 per part; larger = 5 parts.","sort_order":9},{"question_text":"A price increases by 20% from $80. What is the new price?","options":["64","96","100","16"],"correct_option":1,"difficulty":"medium","explanation":"Multiplier 1.20: 80 × 1.2 = 96.","sort_order":10}]$json$),
  ('mathematics', "1.6", null, "Calculator, time, money, growth/decay and surds — Core Paper 3 (calculator)", $json$[{"question_text":"Simple interest on $200 at 10% per year for 2 years:","options":["42","20","40","240"],"correct_option":2,"difficulty":"medium","explanation":"I = Prt/100 = 200×10×2/100 = 40.","sort_order":1},{"question_text":"Simple interest on $1000 at 20% per year for 2 years:","options":["400","1400","200","440"],"correct_option":0,"difficulty":"medium","explanation":"I = Prt/100 = 1000×20×2/100 = 400.","sort_order":2},{"question_text":"Simple interest on $1000 at 20% per year for 3 years:","options":["600","728","1600","200"],"correct_option":0,"difficulty":"medium","explanation":"I = Prt/100 = 1000×20×3/100 = 600.","sort_order":3},{"question_text":"Simple interest on $200 at 5% per year for 2 years:","options":["20.5","220","10","20"],"correct_option":3,"difficulty":"medium","explanation":"I = Prt/100 = 200×5×2/100 = 20.","sort_order":4},{"question_text":"Simple interest on $100 at 5% per year for 2 years:","options":["10.25","10","5","110"],"correct_option":1,"difficulty":"medium","explanation":"I = Prt/100 = 100×5×2/100 = 10.","sort_order":5},{"question_text":"Simple interest on $1000 at 5% per year for 2 years:","options":["50","1100","100","102.5"],"correct_option":2,"difficulty":"medium","explanation":"I = Prt/100 = 1000×5×2/100 = 100.","sort_order":6},{"question_text":"Simple interest on $500 at 10% per year for 3 years:","options":["150","165.5","50","650"],"correct_option":0,"difficulty":"medium","explanation":"I = Prt/100 = 500×10×3/100 = 150.","sort_order":7},{"question_text":"Simple interest on $500 at 5% per year for 2 years:","options":["550","25","51.25","50"],"correct_option":3,"difficulty":"medium","explanation":"I = Prt/100 = 500×5×2/100 = 50.","sort_order":8},{"question_text":"Simple interest on $1000 at 10% per year for 2 years:","options":["100","200","1200","210"],"correct_option":1,"difficulty":"medium","explanation":"I = Prt/100 = 1000×10×2/100 = 200.","sort_order":9},{"question_text":"Simple interest on $100 at 5% per year for 3 years:","options":["5","15.763","15","115"],"correct_option":2,"difficulty":"medium","explanation":"I = Prt/100 = 100×5×3/100 = 15.","sort_order":10}]$json$),
  ('mathematics', "2.1", null, "Algebraic language, manipulation and fractions — Core Paper 3 (calculator)", $json$[{"question_text":"Expand 4(x + 2) − 6x.","options":["-2x + 8","4x + 2","10x + 8","-2x − 8"],"correct_option":0,"difficulty":"medium","explanation":"4x + 8 − 6x = -2x + 8.","sort_order":1},{"question_text":"Factorise x² + 9x + 20.","options":["(x + 20)(x + 1)","(x + 4)(x + 5)","(x − 4)(x − 5)","(x + 4)(x − 5)"],"correct_option":1,"difficulty":"medium","explanation":"4 + 5 = 9 and 4 × 5 = 20.","sort_order":2},{"question_text":"Expand 3(x + 4) − 3x.","options":["0x + 12","0x − 12","6x + 12","3x + 9"],"correct_option":0,"difficulty":"medium","explanation":"3x + 12 − 3x = 0x + 12.","sort_order":3},{"question_text":"Factorise x² + 10x + 21.","options":["(x + 7)(x + 3)","(x + 7)(x − 3)","(x − 7)(x − 3)","(x + 21)(x + 1)"],"correct_option":0,"difficulty":"medium","explanation":"7 + 3 = 10 and 7 × 3 = 21.","sort_order":4},{"question_text":"Expand 2(x + 4) − 6x.","options":["8x + 8","-4x + 8","-4x − 8","2x + 2"],"correct_option":1,"difficulty":"medium","explanation":"2x + 8 − 6x = -4x + 8.","sort_order":5},{"question_text":"Factorise x² + 6x + 8.","options":["(x + 2)(x − 4)","(x − 2)(x − 4)","(x + 2)(x + 4)","(x + 8)(x + 1)"],"correct_option":2,"difficulty":"medium","explanation":"2 + 4 = 6 and 2 × 4 = 8.","sort_order":6},{"question_text":"Expand 3(x + 2) − 5x.","options":["-2x + 6","3x + 1","8x + 6","-2x − 6"],"correct_option":0,"difficulty":"medium","explanation":"3x + 6 − 5x = -2x + 6.","sort_order":7},{"question_text":"Factorise x² + 13x + 42.","options":["(x + 7)(x + 6)","(x + 42)(x + 1)","(x + 7)(x − 6)","(x − 7)(x − 6)"],"correct_option":0,"difficulty":"medium","explanation":"7 + 6 = 13 and 7 × 6 = 42.","sort_order":8},{"question_text":"Expand 5(x + 2) − 5x.","options":["10x + 10","0x + 10","5x + 5","0x − 10"],"correct_option":1,"difficulty":"medium","explanation":"5x + 10 − 5x = 0x + 10.","sort_order":9},{"question_text":"Factorise x² + 11x + 18.","optio