  ('mathematics', "1.1", null, "Types of number, sets, powers and roots — Extended Paper 2 (non-calculator)", $json$[{"question_text":"Find the HCF of 18 and 22.","options":["5","4","7","2"],"correct_option":3,"difficulty":"medium","explanation":"Common factors of 18 and 22 give HCF = 2.","sort_order":1},{"question_text":"Find the LCM of 6 and 24.","options":["25","144","12","24"],"correct_option":3,"difficulty":"medium","explanation":"LCM = (6 × 24) ÷ HCF(6) = 24.","sort_order":2},{"question_text":"Find the LCM of 15 and 24.","options":["120","60","24","360"],"correct_option":0,"difficulty":"medium","explanation":"LCM = (15 × 24) ÷ HCF(3) = 120.","sort_order":3},{"question_text":"Find the HCF of 36 and 46.","options":["2","5","4","10"],"correct_option":0,"difficulty":"medium","explanation":"Common factors of 36 and 46 give HCF = 2.","sort_order":4},{"question_text":"Find the LCM of 8 and 14.","options":["56","28","112","14"],"correct_option":0,"difficulty":"medium","explanation":"LCM = (8 × 14) ÷ HCF(2) = 56.","sort_order":5},{"question_text":"Find the HCF of 12 and 18.","options":["12","7","8","6"],"correct_option":3,"difficulty":"medium","explanation":"Common factors of 12 and 18 give HCF = 6.","sort_order":6},{"question_text":"Find the LCM of 9 and 16.","options":["144","145","16","72"],"correct_option":0,"difficulty":"medium","explanation":"LCM = (9 × 16) ÷ HCF(1) = 144.","sort_order":7},{"question_text":"Find the HCF of 48 and 52.","options":["8","5","4","6"],"correct_option":2,"difficulty":"medium","explanation":"Common factors of 48 and 52 give HCF = 4.","sort_order":8},{"question_text":"Find the LCM of 10 and 21.","options":["21","211","210","105"],"correct_option":2,"difficulty":"medium","explanation":"LCM = (10 × 21) ÷ HCF(1) = 210.","sort_order":9},{"question_text":"Find the HCF of 8 and 20.","options":["6","4","12","8"],"correct_option":1,"difficulty":"medium","explanation":"Common factors of 8 and 20 give HCF = 4.","sort_order":10}]$json$),
