  ('mathematics', "1.3", null, "Indices and standard form — Extended Paper 2 (non-calculator)", $json$[{"question_text":"Simplify (3x^3) × (3x^4).","options":["9x^-1","6x^7","9x^7","9x^12"],"correct_option":2,"difficulty":"medium","explanation":"Multiply coefficients (3×3=9) and add indices (3+4=7).","sort_order":1},{"question_text":"Write 8 as 2 to a power × 2. What power is needed?","options":["1","3","4","2"],"correct_option":3,"difficulty":"medium","explanation":"2^2 = 4, and 4 × 2 = 8.","sort_order":2},{"question_text":"A number in standard form is A × 10^n with 1 ≤ A < 10. Which n suits 600 000?","options":["7","5","6","4"],"correct_option":1,"difficulty":"medium","explanation":"600 000 = 6 × 10^5.","sort_order":3},{"question_text":"Simplify (3x^5) × (3x^3).","options":["9x^2","9x^8","6x^8","9x^15"],"correct_option":1,"difficulty":"medium","explanation":"Multiply coefficients (3×3=9) and add indices (5+3=8).","sort_order":4},{"question_text":"Write 72 as 2 to a power × 9. What power is needed?","options":["3","6","2","4"],"correct_option":0,"difficulty":"medium","explanation":"2^3 = 8, and 8 × 9 = 72.","sort_order":5},{"question_text":"A number in standard form is A × 10^n with 1 ≤ A < 10. Which n suits 300 000?","options":["4","6","5","7"],"correct_option":2,"difficulty":"medium","explanation":"300 000 = 3 × 10^5.","sort_order":6},{"question_text":"Simplify (5x^4) × (5x^3).","options":["10x^7","25x^12","25x^7","25x^1"],"correct_option":2,"difficulty":"medium","explanation":"Multiply coefficients (5×5=25) and add indices (4+3=7).","sort_order":7},{"question_text":"Write 324 as 3 to a power × 4. What power is needed?","options":["5","8","3","4"],"correct_option":3,"difficulty":"medium","explanation":"3^4 = 81, and 81 × 4 = 324.","sort_order":8},{"question_text":"A number in standard form is A × 10^n with 1 ≤ A < 10. Which n suits 400 000?","options":["7","5","6","4"],"correct_option":1,"difficulty":"medium","explanation":"400 000 = 4 × 10^5.","sort_order":9},{"