  ('mathematics', "1.4", null, "Estimation, rounding and bounds — Extended Paper 2 (non-calculator)", $json$[{"question_text":"A length is 7.3 cm to the nearest 0.1 cm. What is its upper bound?","options":["7.4 (check)","7.3","7.45","7.4"],"correct_option":3,"difficulty":"medium","explanation":"Upper bound = 7.3 + 0.05 = 7.4.","sort_order":1},{"question_text":"Round 661 to 2 significant figures.","options":["660","670","700","661"],"correct_option":0,"difficulty":"medium","explanation":"The second significant figure is the tens digit: 660.","sort_order":2},{"question_text":"A length is 0.7 cm to the nearest 0.1 cm. What is its upper bound?","options":["0.7","0.8","0.85","0.8 (check)"],"correct_option":1,"difficulty":"medium","explanation":"Upper bound = 0.7 + 0.05 = 0.8.","sort_order":3},{"question_text":"Round 206 to 2 significant figures.","options":["210","220","200","206"],"correct_option":0,"difficulty":"medium","explanation":"The second significant figure is the tens digit: 210.","sort_order":4},{"question_text":"A length is 7.9 cm to the nearest 0.1 cm. What is its upper bound?","options":["8","7.9","8 (check)","8.05"],"correct_option":0,"difficulty":"medium","explanation":"Upper bound = 7.9 + 0.05 = 8.","sort_order":5},{"question_text":"Round 580 to 2 significant figures.","options":["580","590","600","581"],"correct_option":0,"difficulty":"medium","explanation":"The second significant figure is the tens digit: 580.","sort_order":6},{"question_text":"A length is 2.5 cm to the nearest 0.1 cm. What is its upper bound?","options":["2.6 (check)","2.6","2.65","2.5"],"correct_option":1,"difficulty":"medium","explanation":"Upper bound = 2.5 + 0.05 = 2.6.","sort_order":7},{"question_text":"Round 801 to 2 significant figures.","options":["802","800","801","810"],"correct_option":1,"difficulty":"medium","explanation":"The second significant figure is the tens digit: 800.","sort_order":8},{"question_text":"A length is 5.4 cm to the nearest 0.1 cm. What is its upper bou