  ('mathematics', "1.5", null, "Ratio, proportion, rates and percentages — Extended Paper 2 (non-calculator)", $json$[{"question_text":"Divide $84 in the ratio 5:7. What is the larger share?","options":["36","49","35","7"],"correct_option":1,"difficulty":"medium","explanation":"84 ÷ 12 parts = $7 per part; larger = 7 parts.","sort_order":1},{"question_text":"A price increases by 25% from $120. What is the new price?","options":["145","30","150","90"],"correct_option":2,"difficulty":"medium","explanation":"Multiplier 1.25: 120 × 1.25 = 150.","sort_order":2},{"question_text":"Divide $60 in the ratio 1:4. What is the larger share?","options":["48","15","12","13"],"correct_option":0,"difficulty":"medium","explanation":"60 ÷ 5 parts = $12 per part; larger = 4 parts.","sort_order":3},{"question_text":"A price increases by 20% from $80. What is the new price?","options":["100","96","16","64"],"correct_option":1,"difficulty":"medium","explanation":"Multiplier 1.20: 80 × 1.2 = 96.","sort_order":4},{"question_text":"Divide $90 in the ratio 2:5. What is the larger share?","options":["25.714","25.714","64.286","12.857"],"correct_option":2,"difficulty":"medium","explanation":"90 ÷ 7 parts = $12.857 per part; larger = 5 parts.","sort_order":5},{"question_text":"A price increases by 25% from $60. What is the new price?","options":["85","75","45","15"],"correct_option":1,"difficulty":"medium","explanation":"Multiplier 1.25: 60 × 1.25 = 75.","sort_order":6},{"question_text":"Divide $120 in the ratio 3:4. What is the larger share?","options":["51.429","68.571","17.143","52.429"],"correct_option":1,"difficulty":"medium","explanation":"120 ÷ 7 parts = $17.143 per part; larger = 4 parts.","sort_order":7},{"question_text":"Divide $120 in the ratio 1:4. What is the larger share?","options":["27","25","24","96"],"correct_option":3,"difficulty":"medium","explanation":"120 ÷ 5 parts = $24 per part; larger = 4 parts.","sort_order":8},{"question_text":"A price increases by 25% from $80. What is the new price?","options":["60","20","105","100"],"correct_option":3,"difficulty":"medium","explanation":"Multiplier 1.25: 80 × 1.25 = 100.","sort_order":9},{"question_text":"Divide $90 in the ratio 1:4. What is the larger share?","options":["72","19","21","18"],"correct_option":0,"difficulty":"medium","explanation":"90 ÷ 5 parts = $18 per part; larger = 4 parts.","sort_order":10}]$json$),
  ('mathematics', "1.6", null, "Calculator, time, money, growth/decay and surds — Extended Paper 2 (non-calculator)", $json$[{"question_text":"Simple interest on $500 at 5% per year for 3 years:","options":["25","75","78.813","575"],"correct_option":1,"difficulty":"medium","explanation":"I = Prt/100 = 500×5×3/100 = 75.","sort_order":1},{"question_text":"Simple interest on $200 at 5% per year for 2 years:","options":["20","10","220","20.5"],"correct_option":0,"difficulty":"medium","explanation":"I = Prt/100 = 200×5×2/100 = 20.","sort_order":2},{"question_text":"Simple interest on $500 at 5% per year for 2 years:","options":["50","550","25","51.25"],"correct_option":0,"difficulty":"medium","explanation":"I = Prt/100 = 500×5×2/100 = 50.","sort_order":3},{"question_text":"Simple interest on $200 at 10% per year for 3 years:","options":["20","66.2","260","60"],"correct_option":3,"difficulty":"medium","explanation":"I = Prt/100 = 200×10×3/100 = 60.","sort_order":4},{"question_text":"Simple interest on $100 at 5% per year for 2 years:","options":["10","10.25","110","5"],"correct_option":0,"difficulty":"medium","explanation":"I = Prt/100 = 100×5×2/100 = 10.","sort_order":5},{"question_text":"Simple interest on $1000 at 5% per year for 3 years:","options":["50","1150","150","157.625"],"correct_option":2,"difficulty":"medium","explanation":"I = Prt/100 = 1000×5×3/100 = 150.","sort_order":6},{"question_text":"Simple interest on $1000 at 10% per year for 3 years:","options":["100","331","300","1300"],"correct_option":2,"difficulty":"medium","explanation":"I = Prt/100 = 1000×10×3/100 = 300.","sort_order":7},{"question_text":"Simple interest on $100 at 10% per year for 3 years:","options":["10","33.1","130","30"],"correct_option":3,"difficulty":"medium","explanation":"I = Prt/100 = 100×10×3/100 = 30.","sort_order":8},{"question_text":"Simple interest on $1000 at 20% per year for 3 years:","options":["728","1600","600","200"],"correct_option":2,"difficulty":"medium","explanation":