  ('mathematics', "2.1", null, "Algebraic language, manipulation and fractions — Extended Paper 2 (non-calculator)", $json$[{"question_text":"Expand 3(x + 8) − 3x.","options":["0x + 24","3x + 21","0x − 24","6x + 24"],"correct_option":0,"difficulty":"medium","explanation":"3x + 24 − 3x = 0x + 24.","sort_order":1},{"question_text":"Factorise x² + 13x + 42.","options":["(x + 6)(x + 7)","(x + 6)(x − 7)","(x − 6)(x − 7)","(x + 42)(x + 1)"],"correct_option":0,"difficulty":"medium","explanation":"6 + 7 = 13 and 6 × 7 = 42.","sort_order":2},{"question_text":"Expand 3(x + 5) − 2x.","options":["3x + 13","1x − 15","5x + 15","1x + 15"],"correct_option":3,"difficulty":"medium","explanation":"3x + 15 − 2x = 1x + 15.","sort_order":3},{"question_text":"Factorise x² + 13x + 40.","options":["(x − 5)(x − 8)","(x + 5)(x − 8)","(x + 40)(x + 1)","(x + 5)(x + 8)"],"correct_option":3,"difficulty":"medium","explanation":"5 + 8 = 13 and 5 × 8 = 40.","sort_order":4},{"question_text":"Expand 6(x + 3) − 5x.","options":["11x + 18","1x − 18","6x + 13","1x + 18"],"correct_option":3,"difficulty":"medium","explanation":"6x + 18 − 5x = 1x + 18.","sort_order":5},{"question_text":"Factorise x² + 15x + 54.","options":["(x + 6)(x + 9)","(x − 6)(x − 9)","(x + 54)(x + 1)","(x + 6)(x − 9)"],"correct_option":0,"difficulty":"medium","explanation":"6 + 9 = 15 and 6 × 9 = 54.","sort_order":6},{"question_text":"Expand 5(x + 4) − 5x.","options":["0x + 20","5x + 15","0x − 20","10x + 20"],"correct_option":0,"difficulty":"medium","explanation":"5x + 20 − 5x = 0x + 20.","sort_order":7},{"question_text":"Factorise x² + 8x + 15.","options":["(x − 3)(x − 5)","(x + 3)(x + 5)","(x + 3)(x − 5)","(x + 15)(x + 1)"],"correct_option":1,"difficulty":"medium","explanation":"3 + 5 = 8 and 3 × 5 = 15.","sort_order":8},{"question_text":"Expand 6(x + 8) − 4x.","options":["10x + 48","2x − 48","6x + 44","2x + 48"],"correct_option":3,"difficulty":"medium","explanation":"6x + 48 − 4x = 2x + 48.","sort_order":9},{"question_text":"Factori