  ('mathematics', "2.2", null, "Equations and rearranging formulae — Extended Paper 2 (non-calculator)", $json$[{"question_text":"Solve 9x + 14 = 86.","options":["8","8.6","7","9"],"correct_option":0,"difficulty":"medium","explanation":"9x = 86 − 14 = 72, so x = 8.","sort_order":1},{"question_text":"Make x the subject: y = 5x − 5. What is x?","options":["5y + 5","(y + 5)/5","y/5 + 5","(y − 5)/5"],"correct_option":1,"difficulty":"medium","explanation":"y + 5 = 5x, so x = (y + 5)/5.","sort_order":2},{"question_text":"Solve 3x + 20 = 38.","options":["7","5","6","9.5"],"correct_option":2,"difficulty":"medium","explanation":"3x = 38 − 20 = 18, so x = 6.","sort_order":3},{"question_text":"Make x the subject: y = 2x − 4. What is x?","options":["y/2 + 4","(y + 4)/2","2y + 4","(y − 4)/2"],"correct_option":1,"difficulty":"medium","explanation":"y + 4 = 2x, so x = (y + 4)/2.","sort_order":4},{"question_text":"Solve 6x + 17 = 59.","options":["8.429","6","7","8"],"correct_option":2,"difficulty":"medium","explanation":"6x = 59 − 17 = 42, so x = 7.","sort_order":5},{"question_text":"Solve 8x + 3 = 27.","options":["3","6","2","4"],"correct_option":0,"difficulty":"medium","explanation":"8x = 27 − 3 = 24, so x = 3.","sort_order":6},{"question_text":"Make x the subject: y = 5x − 9. What is x?","options":["(y + 9)/5","(y − 9)/5","y/5 + 9","5y + 9"],"correct_option":0,"difficulty":"medium","explanation":"y + 9 = 5x, so x = (y + 9)/5.","sort_order":7},{"question_text":"Solve 5x + 13 = 23.","options":["2","3.833","1","3"],"correct_option":0,"difficulty":"medium","explanation":"5x = 23 − 13 = 10, so x = 2.","sort_order":8},{"question_text":"Solve 9x + 7 = 52.","options":["6","4","5","5.2"],"correct_option":2,"difficulty":"medium","explanation":"9x = 52 − 7 = 45, so x = 5.","sort_order":9},{"question_text":"Make x the subject: y = 4x − 7. What is x?","options":["4y + 7","y/4 + 7","(y − 7)/4","(y + 7)/4"],"correct_option":3,"difficulty":"medium","explanation":"y + 7 = 4x, so x = (y + 7)/4.","sort_order":10}]$json$),
  ('mathematics', "2.3", null, "Inequalities and sequences — Extended Paper 2 (non-calculator)", $json$[{"question_text":"Solve the inequality 2x > 72 and pick the correct solution.","options":["x > 36","x < 36","x > 72","x < 72"],"correct_option":0,"difficulty":"medium","explanation":"Divide both sides by 2 (positive, so the sign stays): x > 36.","sort_order":1},{"question_text":"Solve the inequality 4x > 160 and pick the correct solution.","options":["x > 40","x < 40","x > 160","x < 160"],"correct_option":0,"difficulty":"medium","explanation":"Divide both sides by 4 (positive, so the sign stays): x > 40.","sort_order":2},{"question_text":"Solve the inequality 5x > 110 and pick the correct solution.","options":["x > 22","x < 22","x > 110","x < 110"],"correct_option":0,"difficulty":"medium","explanation":"Divide both sides by 5 (positive, so the sign stays): x > 22.","sort_order":3},{"question_text":"Solve the inequality 7x > 217 and pick the correct solution.","options":["x > 31","x < 31","x > 217","x < 217"],"correct_option":0,"difficulty":"medium","explanation":"Divide both sides by 7 (positive, so the sign stays): x > 31.","sort_order":4},{"question_text":"Solve the inequality 7x > 98 and pick the correct solution.","options":["x > 14","x < 14","x > 98","x < 98"],"correct_option":0,"difficulty":"medium","explanation":"Divide both sides by 7 (positive, so the sign stays): x > 14.","sort_order":5},{"question_text":"Solve the inequality 8x > 184 and pick the correct solution.","options":["x > 23","x < 23","x > 184","x < 184"],"correct_option":0,"difficulty":"medium","explanation":"Divide both sides by 8 (positive, so the sign stays): x > 23.","sort_order":6},{"question_text":"Solve the inequality 4x > 72 and pick the correct solution.","options":["x > 18","x < 18","x > 72","x < 72"],"correct_option":0,"difficulty":"medium","explanation":"Divide both sides by 4 (positive, so the sign stays): x > 18.","sort_order":7},{"question_text":"Solve the inequality 8x > 216 an