  ('mathematics', "3.1", null, "Coordinates, gradients, distance and midpoint — Extended Paper 2 (non-calculator)", $json$[{"question_text":"Find the distance between (-2, -4) and (4, -1).","options":["3","18","9","6.708"],"correct_option":3,"difficulty":"medium","explanation":"√(6² + 3²) = √45 ≈ 6.708.","sort_order":1},{"question_text":"Find the midpoint of (-4, 3) and (-1, 7).","options":["(-2.5, 5)","(1.5, 2)","(-1, 7)","(-4, 3)"],"correct_option":0,"difficulty":"medium","explanation":"Average each coordinate: ((-4+-1)/2, (3+7)/2).","sort_order":2},{"question_text":"Find the distance between (-2, 2) and (2, 5).","options":["12","1","7","5"],"correct_option":3,"difficulty":"medium","explanation":"√(4² + 3²) = √25 ≈ 5.","sort_order":3},{"question_text":"Find the midpoint of (1, 1) and (4, 3).","options":["(1, 1)","(2.5, 2)","(4, 3)","(1.5, 1)"],"correct_option":1,"difficulty":"medium","explanation":"Average each coordinate: ((1+4)/2, (1+3)/2).","sort_order":4},{"question_text":"Find the distance between (0, -4) and (4, 0).","options":["5.657","16","8","0"],"correct_option":0,"difficulty":"medium","explanation":"√(4² + 4²) = √32 ≈ 5.657.","sort_order":5},{"question_text":"Find the midpoint of (0, 2) and (3, 3).","options":["(1.5, 0.5)","(0, 2)","(3, 3)","(1.5, 2.5)"],"correct_option":3,"difficulty":"medium","explanation":"Average each coordinate: ((0+3)/2, (2+3)/2).","sort_order":6},{"question_text":"Find the distance between (0, 1) and (4, 4).","options":["7","1","5","12"],"correct_option":2,"difficulty":"medium","explanation":"√(4² + 3²) = √25 ≈ 5.","sort_order":7},{"question_text":"Find the midpoint of (-3, 0) and (2, 2).","options":["(-3, 0)","(2.5, 1)","(-0.5, 1)","(2, 2)"],"correct_option":2,"difficulty":"medium","explanation":"Average each coordinate: ((-3+2)/2, (0+2)/2).","sort_order":8},{"question_text":"Find the distance between (0, 2) and (3, 8).","options":["18","6.708","9","3"],"correct_option":1,"difficulty":"medium","explanation":"√(3² + 6²) = √45 ≈ 6.708.","sort_order":9},{"question_text":"Find the midpoint of (-2, 1) and (3, 4).","options":["(3, 4)","(0.5, 2.5)","(-2, 1)","(2.5, 1.5)"],"correct_option":1,"difficulty":"medium","explanation":"Average each coordinate: ((-2+3)/2, (1+4)/2).","sort_order":10}]$json$),
