  ('mathematics', "6.2", null, "Exact trig, trig graphs, non-right-angled triangles and 3D — Extended Paper 2 (non-calculator)", $json$[{"question_text":"Evaluate 7 + 5 × 9.","options":["108","52","315","68"],"correct_option":1,"difficulty":"medium","explanation":"Multiplication first: 5 × 9 = 45; 7 + 45 = 52.","sort_order":1},{"question_text":"Simplify 12x + 9x.","options":["3x","21x²","108x","21x"],"correct_option":3,"difficulty":"medium","explanation":"Like terms: (12 + 9)x = 21x.","sort_order":2},{"question_text":"Evaluate 2 + 9 × 5.","options":["19","90","55","47"],"correct_option":3,"difficulty":"medium","explanation":"Multiplication first: 9 × 5 = 45; 2 + 45 = 47.","sort_order":3},{"question_text":"Simplify 8x + 4x.","options":["12x","32x","12x²","4x"],"correct_option":0,"difficulty":"medium","explanation":"Like terms: (8 + 4)x = 12x.","sort_order":4},{"question_text":"Evaluate 7 + 6 × 2.","options":["19","26","84","20"],"correct_option":0,"difficulty":"medium","explanation":"Multiplication first: 6 × 2 = 12; 7 + 12 = 19.","sort_order":5},{"question_text":"Simplify 6x + 6x.","options":["0x","12x","12x²","36x"],"correct_option":1,"difficulty":"medium","explanation":"Like terms: (6 + 6)x = 12x.","sort_order":6},{"question_text":"Evaluate 8 + 4 × 4.","options":["24","48","128","36"],"correct_option":0,"difficulty":"medium","explanation":"Multiplication first: 4 × 4 = 16; 8 + 16 = 24.","sort_order":7},{"question_text":"Simplify 3x + 8x.","options":["24x","11x","-5x","11x²"],"correct_option":1,"difficulty":"medium","explanation":"Like terms: (3 + 8)x = 11x.","sort_order":8},{"question_text":"Evaluate 3 + 5 × 6.","options":["90","23","48","33"],"correct_option":3,"difficulty":"medium","explanation":"Multiplication first: 5 × 6 = 30; 3 + 30 = 33.","sort_order":9},{"question_text":"Simplify 4x + 7x.","options":["28x","11x","-3x","11x²"],"correct_option":1,"difficulty":"medium","explanation":"Like terms: (4 + 7)x = 11x.","sort_order":10}]$json$),
  ('mathematics', "8.2", null, "Conditional probability — Extended Paper 2 (non-calculator)", $json$[{"question_text":"A bag has 5 green and 2 yellow balls. P(green) as a fraction:","options":["5/7","5/2","2/7","1/7"],"correct_option":0,"difficulty":"medium","explanation":"5 of 7 balls are green.","sort_order":1},{"question_text":"A bag has 5 green and 5 yellow balls. P(green) as a fraction:","options":["5/10 (check)","5/5","1/10","5/10"],"correct_option":3,"difficulty":"medium","explanation":"5 of 10 balls are green.","sort_order":2},{"question_text":"A bag has 3 green and 3 yellow balls. P(green) as a fraction:","options":["3/3","3/6","3/6 (check)","1/6"],"correct_option":1,"difficulty":"medium","explanation":"3 of 6 balls are green.","sort_order":3},{"question_text":"A bag has 3 green and 4 yellow balls. P(green) as a fraction:","options":["3/4","1/7","4/7","3/7"],"correct_option":3,"difficulty":"medium","explanation":"3 of 7 balls are green.","sort_order":4},{"question_text":"A bag has 2 green and 3 yellow balls. P(green) as a fraction:","options":["2/3","3/5","2/5","1/5"],"correct_option":2,"difficulty":"medium","explanation":"2 of 5 balls are green.","sort_order":5},{"question_text":"A bag has 5 green and 4 yellow balls. P(green) as a fraction:","options":["5/4","5/9","1/9","4/9"],"correct_option":1,"difficulty":"medium","explanation":"5 of 9 balls are green.","sort_order":6},{"question_text":"A bag has 4 green and 5 yellow balls. P(green) as a fraction:","options":["4/5","5/9","1/9","4/9"],"correct_option":3,"difficulty":"medium","explanation":"4 of 9 balls are green.","sort_order":7},{"question_text":"A bag has 5 green and 3 yellow balls. P(green) as a fraction:","options":["1/8","5/8","5/3","3/8"],"correct_option":1,"difficulty":"medium","explanation":"5 of 8 balls are green.","sort_order":8},{"question_text":"A bag has 2 green and 4 yellow balls. P(green) as a fraction:","options":["4/6","2/6","2/4","1/6"],"correct_option":1,"difficulty":"medium","explanation":"2 of 6 balls are green.","sort_order":9},{"question_text":"A bag has 4 green and 3 yellow balls. P(green) as a fraction:","options":["3/7","4/3","4/7","1/7"],"correct_option":2,"difficulty":"medium","explanation":"4 of 7 balls are green.","sort_order":10}]$json$),
  ('mathematics', "9.1", null, "Data, averages and displays — Extended Paper 2 (non-calculator)", $json$[{"question_text":"Find the mean of 9, 2, 7, 9, 4.","options":["7 (check)","6.2","31","7"],"correct_option":1,"difficulty":"medium","explanation":"Sum 31 ÷ 5 = 6.2.","sort_order":1},{"question_text":"Find the median of 3, 5, 1, 4, 2.","options":["3","2","3 (check)","4"],"correct_option":0,"difficulty":"medium","explanation":"Ordered: 1, 2, 3, 4, 5; middle value is 3.","sort_order":2},{"question_text":"Find the mean of 9, 8, 9, 8, 8.","options":["1","42","8.4","8"],"correct_option":2,"difficulty":"medium","explanation":"Sum 42 ÷ 5 = 8.4.","sort_order":3},{"question_text":"Find the median of 4, 1, 3, 6, 2, 5, 7.","options":["5","3","4","4 (check)"],"correct_option":2,"difficulty":"medium","explanation":"Ordered: 1, 2, 3, 4, 5, 6, 7; middle value is 4.","sort_order":4},{"question_text":"Find the mean of 6, 6, 7, 4, 7.","options":["6 (check)","3","30","6"],"correct_option":3,"difficulty":"medium","explanation":"Sum 30 ÷ 5 = 6.","sort_order":5},{"question_text":"Find the median of 3, 2, 6, 1, 7, 4, 5.","options":["4 (check)","5","4","3"],"correct_option":2,"difficulty":"medium","explanation":"Ordered: 1, 2, 3, 4, 5, 6, 7; middle value is 4.","sort_order":6},{"question_text":"Find the mean of 4, 6, 7, 9, 6.","options":["32","6.4","5","6"],"correct_option":1,"difficulty":"medium","explanation":"Sum 32 ÷ 5 = 6.4.","sort_order":7},{"question_text":"Find the median of 1, 2, 3, 4, 5.","options":["3 (check)","4","3","2"],"correct_option":2,"difficulty":"medium","explanation":"Ordered: 1, 2, 3, 4, 5; middle value is 3.","sort_order":8},{"question_text":"Find the mean of 2, 3, 7, 8, 4.","options":["24","4","4.8","6"],"correct_option":2,"difficulty":"medium","explanation":"Sum 24 ÷ 5 = 4.8.","sort_order":9},{"question_text":"Find the median of 1, 2, 5, 6, 4, 3.","options":["3.5","5","4","3"],"correct_option":2,"difficulty":"medium","explanation":"Ordered: 1, 2, 3, 4, 5, 6; middle value is 4.","sort_order":10}]$json$),
  ('mathematics', "1.1", null, "Types of number, sets, powers and roots — Extended Paper 4 (calculator)", $json$[{"question_text":"Find the HCF of 24 and 28.","options":["5","6","8","4"],"correct_option":3,"difficulty":"medium","explanation":"Common factors of 24 and 28 give HCF = 4.","sort_order":1},{"question_text":"Find the LCM of 6 and 20.","options":["60","20","30","120"],"correct_option":0,"difficulty":"medium","explanation":"LCM = (6 × 20) ÷ HCF(2) = 60.","sort_order":2},{"question_text":"Find the HCF of 18 and 28.","options":["2","5","10","4"],"correct_option":0,"difficulty":"medium","explanation":"Common factors of 18 and 28 give HCF = 2.","sort_order":3},{"question_text":"Find the LCM of 8 and 18.","options":["144","18","36","72"],"correct_option":3,"difficulty":"medium","explanation":"LCM = (8 × 18) ÷ HCF(2) = 72.","sort_order":4},{"question_text":"Find the HCF of 12 and 22.","options":["2","10","4","5"],"correct_option":0,"difficulty":"medium","explanation":"Common factors of 12 and 22 give HCF = 2.","sort_order":5},{"question_text":"Find the LCM of 6 and 18.","options":["19","18","9","108"],"correct_option":1,"difficulty":"medium","explanation":"LCM = (6 × 18) ÷ HCF(6) = 18.","sort_order":6},{"question_text":"Find the HCF of 30 and 34.","options":["4","2","7","5"],"correct_option":1,"difficulty":"medium","explanation":"Common factors of 30 and 34 give HCF = 2.","sort_order":7},{"question_text":"Find the LCM of 6 and 21.","options":["22","126","42","21"],"correct_option":2,"difficulty":"medium","explanation":"LCM = (6 × 21) ÷ HCF(3) = 42.","sort_order":8},{"question_text":"Find the HCF of 8 and 26.","options":["2","4","5","18"],"correct_option":0,"difficulty":"medium","explanation":"Common factors of 8 and 26 give HCF = 2.","sort_order":9},{"question_text":"Find the LCM of 9 and 24.","options":["72","216","24","36"],"correct_option":0,"difficulty":"medium","explanation":"LCM = (9 × 24) ÷ HCF(3) = 72.","sort_order":10}]$json$),
  ('mathematics', "1.2", null, "Fractions, decimals, percentages, ordering and operations — Extended Paper 4 (calculator)", $json$[{"question_text":"Write 8/13 in its simplest form.","options":["9/14","13/8","16/26","8/13"],"correct_option":3,"difficulty":"medium","explanation":"Divide numerator and denominator by 1.","sort_order":1},{"question_text":"Work out 40% of 60.","options":["24","2.4","20","240"],"correct_option":0,"difficulty":"medium","explanation":"40% of 60 = 40/100 × 60 = 24.","sort_order":2},{"question_text":"Work out 3/2 + 6/6 in simplest form (answer as fraction).","options":["6/12","9/8","30/12","18/12"],"correct_option":2,"difficulty":"medium","explanation":"Common denominator 12: (18 + 12)/12.","sort_order":3},{"question_text":"Write 5/7 in its simplest form.","options":["5/7","6/8","7/5","10/14"],"correct_option":0,"difficulty":"medium","explanation":"Divide numerator and denominator by 1.","sort_order":4},{"question_text":"Work out 40% of 40.","options":["0","160","1.6","16"],"correct_option":3,"difficulty":"medium","explanation":"40% of 40 = 40/100 × 40 = 16.","sort_order":5},{"question_text":"Work out 2/9 + 6/9 in simplest form (answer as fraction).","options":["8/18","72/81","12/81","-36/81"],"correct_option":1,"difficulty":"medium","explanation":"Common denominator 81: (18 + 54)/81.","sort_order":6},{"question_text":"Write 5/6 in its simplest form.","options":["6/7","6/5","10/12","5/6"],"correct_option":3,"difficulty":"medium","explanation":"Divide numerator and denominator by 1.","sort_order":7},{"question_text":"Work out 15% of 80.","options":["1.2","65","120","12"],"correct_option":3,"difficulty":"medium","explanation":"15% of 80 = 15/100 × 80 = 12.","sort_order":8},{"question_text":"Work out 6/4 + 3/7 in simplest form (answer as fraction).","options":["54/28","9/11","30/28","18/28"],"correct_option":0,"difficulty":"medium","explanation":"Common denominator 28: (42 + 12)/28.","sort_order":9},{"question_text":"Write 8/12 in its simplest form.","options":["3/2","9/13","2/3","16/24"],"correct_option":2,"difficulty":"medium","explanation":"Divide numerator and denominator by 4.","sort_order":10}]$json$),
  ('mathematics', "1.3", null, "Indices and standard form — Extended Paper 4 (calculator)", $json$[{"question_text":"Simplify (6x^5) × (6x^2).","options":["12x^7","36x^7","36x^10","36x^3"],"correct_option":1,"difficulty":"medium","explanation":"Multiply coefficients (6×6=36) and add indices (5+2=7).","sort_order":1},{"question_text":"Write 96 as 4 to a power × 6. What power is needed?","options":["2","4","1","3"],"correct_option":0,"difficulty":"medium","explanation":"4^2 = 16, and 16 × 6 = 96.","sort_order":2},{"question_text":"A number in standard form is A × 10^n with 1 ≤ A < 10. Which n suits 700 000?","options":["6","5","7","4"],"correct_option":1,"difficulty":"medium","explanation":"700 000 = 7 × 10^5.","sort_order":3},{"question_text":"Simplify (3x^3) × (3x^4).","options":["6x^7","9x^12","9x^-1","9x^7"],"correct_option":3,"difficulty":"medium","explanation":"Multiply coefficients (3×3=9) and add indices (3+4=7).","sort_order":4},{"question_text":"Write 1125 as 5 to a power × 9. What power is needed?","options":["4","2","3","6"],"correct_option":2,"difficulty":"medium","explanation":"5^3 = 125, and 125 × 9 = 1125.","sort_order":5},{"question_text":"Simplify (6x^4) × (6x^2).","options":["36x^8","36x^6","12x^6","36x^2"],"correct_option":1,"difficulty":"medium","explanation":"Multiply coefficients (6×6=36) and add indices (4+2=6).","sort_order":6},{"question_text":"Write 225 as 5 to a power × 9. What power is needed?","options":["3","2","4","1"],"correct_option":1,"difficulty":"medium","explanation":"5^2 = 25, and 25 × 9 = 225.","sort_order":7},{"question_text":"Simplify (3x^5) × (3x^3).","options":["9x^15","9x^2","6x^8","9x^8"],"correct_option":3,"difficulty":"medium","explanation":"Multiply coefficients (3×3=9) and add indices (5+3=8).","sort_order":8},{"question_text":"Write 24 as 2 to a power × 6. What power is needed?","options":["4","1","3","2"],"correct_option":3,"difficulty":"medium","explanation":"2^2 = 4, and 4 × 6 = 24.","sort_order":9},{"question_text":"A number in standard form is A × 10^n with 1 ≤ A < 10. Which n suits 800 000?","options":["5","6","4","7"],"correct_option":0,"difficulty":"medium","explanation":"800 000 = 8 × 10^5.","sort_order":10}]$json$),
  ('mathematics', "1.4", null, "Estimation, rounding and bounds — Extended Paper 4 (calculator)", $json$[{"question_text":"A length is 6.4 cm to the nearest 0.1 cm. What is its upper bound?","options":["6.5","6.5 (check)","6.4","6.55"],"correct_option":0,"difficulty":"medium","explanation":"Upper bound = 6.4 + 0.05 = 6.5.","sort_order":1},{"question_text":"Round 680 to 2 significant figures.","options":["700","680","681","690"],"correct_option":1,"difficulty":"medium","explanation":"The second significant figure is the tens digit: 680.","sort_order":2},{"question_text":"A length is 2.9 cm to the nearest 0.1 cm. What is its upper bound?","options":["3.05","2.9","3","3 (check)"],"correct_option":2,"difficulty":"medium","explanation":"Upper bound = 2.9 + 0.05 = 3.","sort_order":3},{"question_text":"Round 158 to 2 significant figures.","options":["200","158","170","160"],"correct_option":3,"difficulty":"medium","explanation":"The second significant figure is the tens digit: 160.","sort_order":4},{"question_text":"A length is 3.4 cm to the nearest 0.1 cm. What is its upper bound?","options":["3.55","3.5 (check)","3.4","3.5"],"correct_option":3,"difficulty":"medium","explanation":"Upper bound = 3.4 + 0.05 = 3.5.","sort_order":5},{"question_text":"Round 442 to 2 significant figures.","options":["442","400","440","450"],"correct_option":2,"difficulty":"medium","explanation":"The second significant figure is the tens digit: 440.","sort_order":6},{"question_text":"A length is 6.9 cm to the nearest 0.1 cm. What is its upper bound?","options":["7","6.9","7 (check)","7.05"],"correct_option":0,"difficulty":"medium","explanation":"Upper bound = 6.9 + 0.05 = 7.","sort_order":7},{"question_text":"Round 804 to 2 significant figures.","options":["800","810","804","801"],"correct_option":0,"difficulty":"medium","explanation":"The second significant figure is the tens digit: 800.","sort_order":8},{"question_text":"A length is 0.4 cm to the nearest 0.1 cm. What is its upper bound?","options":["0.5 (check)","0.4","0.5","0.55"],"correct_option":2,"difficulty":"medium","explanation":"Upper bound = 0.4 + 0.05 = 0.5.","sort_order":9},{"question_text":"Round 359 to 2 significant figures.","options":["370","359","400","360"],"correct_option":3,"difficulty":"medium","explanation":"The second significant figure is the tens digit: 360.","sort_order":10}]$json$),
