  ('physics', "4.1", "4.1", "Simple phenomena of magnetism — P1 Multiple Choice (Core)", $json$[{"question_text":"A current of 4 A flows through a 5 Ω resistor. The p.d. across it is:","options":["10","0.8","20","1.25"],"correct_option":2,"difficulty":"medium","explanation":"V = IR = 4 × 5 = 20 V.","sort_order":1},{"question_text":"A 36 W lamp runs on a 6 V supply. The current it draws is:","options":["0.167","216","12","6"],"correct_option":3,"difficulty":"medium","explanation":"I = P/V = 36/6 = 6 A.","sort_order":2},{"question_text":"A current of 0.5 A flows for 120 s. The charge transferred is:","options":["120","240","60","0.004"],"correct_option":2,"difficulty":"medium","explanation":"Q = It = 0.5 × 120 = 60 C.","sort_order":3},{"question_text":"Two resistors, 3 Ω and 12 Ω, are connected in parallel. The combined resistance is:","options":["15","2.4","9","4.8"],"correct_option":1,"difficulty":"medium","explanation":"1/R = 1/3 + 1/12 → R = (3×12)/(3+12) = 2.4 Ω.","sort_order":4},{"question_text":"A transformer has 500 primary turns and a primary p.d. of 120 V. For a 60 V output, the secondary turns needed are:","options":["250","560","500","1000"],"correct_option":0,"difficulty":"medium","explanation":"Ns = Np × Vs/Vp = 500 × 60/120 = 250 turns.","sort_order":5},{"question_text":"A current of 2 A flows through a 2 Ω resistor. The p.d. across it is:","options":["4","2","1 (check)","1"],"correct_option":0,"difficulty":"medium","explanation":"V = IR = 2 × 2 = 4 V.","sort_order":6},{"question_text":"A 100 W lamp runs on a 6 V supply. The current it draws is:","options":["0.06","33.333","600","16.667"],"correct_option":3,"difficulty":"medium","explanation":"I = P/V = 100/6 = 16.667 A.","sort_order":7},{"question_text":"A current of 3 A flows for 120 s. The charge transferred is:","options":["40","0.025","720","360"],"correct_option":3,"difficulty":"medium","explanation":"Q = It = 3 × 120 = 360 C.","sort_order":8},{"question_text":"Two resistors, 6 Ω and 8 Ω, are connected in parallel. The combined resistance is:","options":["14","3.429","2","6.857"],"correct_option":1,"difficulty":"medium","explanation":"1/R = 1/6 + 1/8 → R = (6×8)/(6+8) = 3.429 Ω.","sort_order":9},{"question_text":"A transformer has 200 primary turns and a primary p.d. of 120 V. For a 60 V output, the secondary turns needed are:","options":["200","260","400","100"],"correct_option":3,"difficulty":"medium","explanation":"Ns = Np × Vs/Vp = 200 × 60/120 = 100 turns.","sort_order":10}]$json$),
